# Generate the self-contained runtime that is shared with standalone FIES scripts.
files <- c("R/fies_output.R", "R/fies_setup.R")
stopifnot(all(file.exists(files)))
code <- unlist(lapply(files, function(path) {
  lines <- readLines(path, warn = FALSE)
  c(lines[!startsWith(lines, "#'")], "")
}), use.names = FALSE)
dir.create("inst/fies", recursive = TRUE, showWarnings = FALSE)
writeLines(c(
  "# Standalone FIES runtime. Requires the listed statistical packages, not micsPlusTableR.",
  "# Generated by tools/build-fies-runtime.R; distribute this file with the FIES helpers.",
  code
), "inst/fies/FIES-runtime.R")
